  // ---- huzogatos szerkesztes: az esemenyek (kartya d4b05d82) ----------------
  //
  // EGY Pointer Events-figyelo lefedi az egeret ES az erintokepernyot is, tehat
  // telefonon ugyanugy mukodik. A huzas KOZBEN nem megy halozati keres: a doboz
  // helyben mozog, es csak az ELENGEDESKOR megy EGY `update` muvelet -- ugyanaz,
  // amit a szamokat kero urlap es az agent is kuldene, tehat a ket ut nem
  // csuszhat szet.

  var canvasDrag = null

  function canvasDragStyle(el, box, doc) {
    if (!el || !el.style) return
    el.style.left = (Math.round((10000 * box.x) / doc.width) / 100) + '%'
    el.style.top = (Math.round((10000 * box.y) / doc.height) / 100) + '%'
    el.style.width = (Math.round((10000 * box.width) / doc.width) / 100) + '%'
    el.style.height = (Math.round((10000 * box.height) / doc.height) / 100) + '%'
  }

  /** Huzas kozben a SZAMOK is latszanak: a felhasznalonak ne kelljen kitalalnia,
   *  hova kerult az elem. Ugyanazok az ertekek, mint a szerkeszto urlapon. */
  function canvasDragLive(box) {
    var el = document.getElementById('wbCanLive')
    if (!el) return
    var text = t('workbench.canvas.drag_live', { x: box.x, y: box.y, w: box.width, h: box.height })
    if ('textContent' in el) el.textContent = text
  }

  /** A segedvonalak kirajzolasa huzas kozben (csak a ket vonal stilusa
   *  valtozik, a vaszon nem rajzolodik ujra). */
  function canvasGuides(guides, doc) {
    ;['x', 'y'].forEach(function (axis) {
      var el = document.getElementById(axis === 'x' ? 'wbCanGuideX' : 'wbCanGuideY')
      if (!el) return
      var g = null
      guides.forEach(function (x) { if (x.axis === axis) g = x })
      if (!g) { el.hidden = true; return }
      el.hidden = false
      if (el.style) {
        if (axis === 'x') el.style.left = (Math.round((10000 * g.at) / doc.width) / 100) + '%'
        else el.style.top = (Math.round((10000 * g.at) / doc.height) / 100) + '%'
      }
    })
  }

  function canvasDragHighlight(stage, boxEl) {
    if (!stage || typeof stage.querySelectorAll !== 'function') return
    var all = stage.querySelectorAll('[data-wb-box]')
    for (var i = 0; i < all.length; i++) {
      all[i].className = 'wb-can-box' + (all[i] === boxEl ? ' wb-can-box-sel' : '')
    }
  }

  document.addEventListener('pointerdown', function (e) {
    if (!WB.open || WB.canvasBusy || archived()) return
    var target = e.target
    if (!target || typeof target.closest !== 'function') return
    var boxEl = target.closest('[data-wb-box]')
    if (!boxEl) return
    var doc = (WB.canvas && WB.canvas.exists && WB.canvas.canvas) || null
    if (!doc) return
    var o = canvasObject(boxEl.getAttribute('data-wb-box'))
    if (!o) return
    var stage = target.closest('[data-wb-stage]')
    var rect = stage && typeof stage.getBoundingClientRect === 'function' ? stage.getBoundingClientRect() : null
    // Meret nelkul nem tudunk kepernyo-pixelbol vaszon-egyseget szamolni.
    // Ilyenkor INKABB nem mozdulunk, mint hogy talalgassunk: az urlap
    // (X, Y, Szelesseg, Magassag) tovabbra is ott van.
    if (!rect || !rect.width || !rect.height) return
    var gripEl = target.closest('[data-wb-grip]')
    if (gripEl && gripEl.getAttribute('data-wb-grip') === 'rot' && typeof boxEl.getBoundingClientRect === 'function') {
      // Forgatas: a doboz kozepe korul; a kezdo szog a mutato iranya a kozepponthoz kepest.
      var br = boxEl.getBoundingClientRect()
      var rcx = br.left + br.width / 2
      var rcy = br.top + br.height / 2
      canvasDrag = {
        id: o.id, mode: 'rot', el: boxEl, doc: doc, moved: false, startX: e.clientX, startY: e.clientY,
        cx: rcx, cy: rcy, a0: Math.atan2(e.clientY - rcy, e.clientX - rcx), rot0: o.rotation || 0, rot: o.rotation || 0,
        from: { x: o.x, y: o.y, width: o.width, height: o.height }, box: { x: o.x, y: o.y, width: o.width, height: o.height },
      }
      WB.canvasSel = o.id
      if (typeof gripEl.setPointerCapture === 'function' && e.pointerId != null) {
        try { gripEl.setPointerCapture(e.pointerId) } catch (err) { /* nem all meg tole a forgatas */ }
      }
      if (typeof e.preventDefault === 'function') e.preventDefault()
      return
    }
    var from = { x: o.x, y: o.y, width: o.width, height: o.height }
    canvasDrag = {
      id: o.id,
      mode: gripEl ? gripEl.getAttribute('data-wb-grip') : 'move',
      from: from,
      box: from,
      startX: e.clientX,
      startY: e.clientY,
      kx: doc.width / rect.width,
      ky: doc.height / rect.height,
      doc: doc,
      el: boxEl,
      moved: false,
      // A tobbi elem (a sajat csoportja nelkul) -- ezekhez illeszkedik.
      others: canvasObjects().filter(function (x) { return x.id !== o.id && !x.rotation }),
      rotated: !!o.rotation,
    }
    var wasSel = WB.canvasSel === o.id
    canvasDrag.wasSel = wasSel
    WB.canvasSel = o.id
    // Shift+kattintas: hozzaadja a kijeloleshez (vagy kiveszi) -- ahogy minden
    // rajzoloprogramban. Huzas ilyenkor nincs.
    if (e.shiftKey) {
      canvasDrag = null
      if (WB.canvasPick[o.id]) delete WB.canvasPick[o.id]
      else WB.canvasPick[o.id] = true
      if (typeof e.preventDefault === 'function') e.preventDefault()
      render()
      return
    }
    canvasDragHighlight(stage, boxEl)
    // A mutato "hozzaragad" a dobozhoz: ha a kez kifut a kepbol, a huzas akkor
    // sem szakad meg.
    if (typeof boxEl.setPointerCapture === 'function' && e.pointerId != null) {
      try { boxEl.setPointerCapture(e.pointerId) } catch (err) { /* nem all meg tole a huzas */ }
    }
    if (typeof e.preventDefault === 'function') e.preventDefault()
  })

  document.addEventListener('pointermove', function (e) {
    var d = canvasDrag
    if (!d) return
    var sx = e.clientX - d.startX
    var sy = e.clientY - d.startY
    if (d.mode === 'rot') {
      if (!d.moved && Math.abs(sx) < 3 && Math.abs(sy) < 3) return
      d.moved = true
      var deg = d.rot0 + ((Math.atan2(e.clientY - d.cy, e.clientX - d.cx) - d.a0) * 180) / Math.PI
      if (e.shiftKey) deg = Math.round(deg / 15) * 15
      deg = ((Math.round(deg) % 360) + 360) % 360
      d.rot = deg
      if (d.el && d.el.style) d.el.style.transform = 'rotate(' + deg + 'deg)'
      var live = document.getElementById('wbCanLive')
      if (live && 'textContent' in live) live.textContent = t('workbench.canvas.rot_live', { deg: deg })
      if (typeof e.preventDefault === 'function') e.preventDefault()
      return
    }
    // Par pixel meg nem huzas, hanem kattintas (kijelolés). Kulonben minden
    // erintes elmozditana az elemet.
    if (!d.moved && Math.abs(sx) < 3 && Math.abs(sy) < 3) return
    d.moved = true
    d.box = canvasDragBox(d.from, d.mode, sx * d.kx, sy * d.ky)
    // Illesztes (K-2.7). Az Alt lenyomva tartasa kikapcsolja erre a huzasra --
    // ugyanugy, mint a Figmaban. A tures 6 kepernyo-pixel, barmekkora a kep.
    // Forgatott elemnel nincs illesztes: a doboza nem az, amit a szem lat.
    var snapped = { box: d.box, guides: [] }
    if ((WB.canvasSnap || WB.canvasGrid) && !e.altKey && !d.rotated) {
      snapped = canvasSnapBox(d.box, d.mode, d.others, d.doc, { tol: 6 * d.kx, guides: WB.canvasSnap, grid: WB.canvasGrid })
      d.box = snapped.box
    }
    canvasGuides(snapped.guides, d.doc)
    canvasDragStyle(d.el, d.box, d.doc)
    canvasDragLive(d.box)
    if (typeof e.preventDefault === 'function') e.preventDefault()
  })

  /** A huzas vege. `commit === false` (megszakitas) eseten NEM mentunk: a
   *  kovetkezo rajzolas visszateszi az elemet oda, ahol a szerveren all. */
  function canvasDragFinish(commit) {
    var d = canvasDrag
    if (!d) return
    canvasDrag = null
    if (d.mode === 'rot') {
      if (!commit || !d.moved || d.rot === d.rot0) { render(); return }
      canvasOps([{ op: 'rotate', id: d.id, angle: d.rot }])
      return
    }
    canvasGuides([], d.doc)
    var b = d.box
    var f = d.from
    var same = b.x === f.x && b.y === f.y && b.width === f.width && b.height === f.height
    // Egyszeru kattintas egy MAR kijelolt elemen: nincs mit ujrarajzolni -- es ne is rajzoljuk, mert a
    // dupla kattintas (helyben szerkesztes) csak akkor jon letre, ha az elem a ket kattintas kozott
    // nem cserelodik ki.
    if (commit && !d.moved && d.wasSel) return
    if (!commit || !d.moved || same) { render(); return }
    // Several ticked elements move together: the dragged one's shift is applied to every ticked one.
    var pk = d.mode === 'move' && WB.canvasPick[d.id] ? canvasPicked() : []
    if (pk.length > 1) {
      var mdx = b.x - f.x, mdy = b.y - f.y
      canvasOps(pk.map(function (id) { return { op: 'move', id: id, dx: mdx, dy: mdy } }))
      return
    }
    canvasOps([{ op: 'update', id: d.id, patch: { x: b.x, y: b.y, width: b.width, height: b.height } }])
  }

  document.addEventListener('pointerup', function () { canvasDragFinish(true) })
  document.addEventListener('pointercancel', function () { canvasDragFinish(false) })

  // ---- the video timeline: select / reorder / trim by pointer (no render while dragging) ------------
  var tlDrag = null

  document.addEventListener('pointerdown', function (e) {
    if (!WB.open || !e.target || typeof e.target.closest !== 'function') return
    var blk = e.target.closest('[data-wb-tl]')
    if (!blk || WB.vtBusy || WB.vtRender) return
    var h = e.target.closest('[data-wb-tlh]')
    var rect = blk.getBoundingClientRect()
    var c = null
    var clips = (vtDoc() || {}).clips || []
    for (var i = 0; i < clips.length; i += 1) if (clips[i].id === blk.getAttribute('data-wb-tl')) c = clips[i]
    if (!c || !rect.width) return
    var kind = h ? h.getAttribute('data-wb-tlh') : 'scrub'
    if (kind === 'm') kind = 'move'
    if (kind === 'scrub') {
      // A click or drag on the block body is the scrubber: the player goes to that spot and the playhead shows the cut.
      var sel = frVtSelClip()
      if (!sel || sel.id !== c.id) {
        WB.vtSel = c.id
        WB.vtSeek = { id: c.id, frac: (e.clientX - rect.left) / rect.width }
        render()
        return
      }
      frVtSeekFrac(c, (e.clientX - rect.left) / rect.width)
    }
    tlDrag = { id: c.id, el: blk, kind: kind, x0: e.clientX, moved: false, clip: c, secPerPx: Math.max(0.1, c.end - c.start) / rect.width, dx: 0, rect: rect }
    if (typeof blk.setPointerCapture === 'function') { try { blk.setPointerCapture(e.pointerId) } catch (_e) { /* synthetic event */ } }
  })

  document.addEventListener('pointermove', function (e) {
    if (!tlDrag) return
    var d = tlDrag
    d.dx = e.clientX - d.x0
    if (d.kind === 'scrub') { frVtSeekFrac(d.clip, (e.clientX - d.rect.left) / d.rect.width); return }
    if (!d.moved && Math.abs(d.dx) < 4) return
    d.moved = true
    if (archived()) return
    if (d.kind === 'move') {
      d.el.style.transform = 'translateX(' + d.dx + 'px)'
      d.el.style.zIndex = '3'
      d.el.classList.add('wb-tl-drag')
    } else {
      var r = d.el.getBoundingClientRect()
      // The visual feedback only: the block grows or shrinks with the handle.
      var base = d.el.getAttribute('data-w0') || String(r.width)
      d.el.setAttribute('data-w0', base)
      var w = Math.max(24, Number(base) + (d.kind === 'r' ? d.dx : -d.dx))
      d.el.style.width = w + 'px'
      d.el.style.flex = 'none'
    }
  })

  function tlFinish() {
    var d = tlDrag
    tlDrag = null
    if (!d) return
    d.el.style.transform = ''
    d.el.classList.remove('wb-tl-drag')
    if (d.kind === 'scrub') return
    if (!d.moved) {
      WB.vtSel = d.id
      render()
      return
    }
    if (archived()) { render(); return }
    if (d.kind === 'move') {
      var from = -1
      var blocks = Array.prototype.slice.call(document.querySelectorAll('[data-wb-tl]'))
      var mid = d.el.getBoundingClientRect().left + d.el.getBoundingClientRect().width / 2 + d.dx
      var to = 0
      blocks.forEach(function (b, i) {
        if (b === d.el) { from = i; return }
        var r = b.getBoundingClientRect()
        if (r.left + r.width / 2 < mid) to += 1
      })
      WB.vtSel = d.id
      if (from < 0 || to === from) { render(); return }
      vtOps([{ op: 'moveClip', id: d.id, to: to + 1 }])
      return
    }
    var secs = Math.round(d.dx * d.secPerPx * 10) / 10
    WB.vtSel = d.id
    if (d.kind === 'l') {
      var ns = Math.max(0, Math.round((d.clip.start + secs) * 10) / 10)
      if (ns >= d.clip.end - 0.1 || ns === d.clip.start) { render(); return }
      vtOps([{ op: 'trimClip', id: d.id, start: ns }])
    } else {
      var ne = Math.round((d.clip.end + secs) * 10) / 10
      if (ne <= d.clip.start + 0.1 || ne === d.clip.end) { render(); return }
      vtOps([{ op: 'trimClip', id: d.id, end: ne }])
    }
  }
  document.addEventListener('pointerup', tlFinish)
  document.addEventListener('pointercancel', function () { if (tlDrag) { tlDrag.el.style.transform = ''; tlDrag = null; render() } })

  // ---- helyben szerkesztes a lapon (Boss, 2026-10-02, TG 7286/7319) ----------
  //
  // "A diaban helyben beirom a cimet, helyben betoltom a fotot, helyben forgatom, kicsinyitem,
  // nagyitom." Minden itteni muvelet UGYANAZT a vaszon-muveletet kuldi (`update`, `rotate`, `add`,
  // `scale`, `order`, `duplicate`, `remove`), amit a gombok es az agent is kuldene: egy allapot.

  WB.canvasEditId = null

  /** A lebego eszkoztar gombjai. */
  function canvasFloatOp(op) {
    var o = WB.canvasSel ? canvasObject(WB.canvasSel) : null
    if (!o || archived() || WB.canvasBusy) return
    if (op === 'smaller' || op === 'bigger' || op === 'rotate' || op === 'front' || op === 'back' || op === 'duplicate') canvasQuickOp(op, o.id)
    else if (op === 'remove') canvasRemoveObject(o.id)
    else if (op === 'bold') canvasOps([{ op: 'update', id: o.id, patch: { bold: !o.bold } }])
    else if (op === 'italic') canvasOps([{ op: 'update', id: o.id, patch: { italic: !o.italic } }])
    else if (op === 'alignleft') canvasOps([{ op: 'update', id: o.id, patch: { align: 'left' } }])
    else if (op === 'aligncenter') canvasOps([{ op: 'update', id: o.id, patch: { align: 'center' } }])
    else if (op === 'alignright') canvasOps([{ op: 'update', id: o.id, patch: { align: 'right' } }])
  }

  /** A colour from the floating toolbar -- its colour field or a brand colour button -- onto the selected element. */
  function canvasFloatColor(prop, hex) {
    var o = WB.canvasSel ? canvasObject(WB.canvasSel) : null
    if (!o || archived() || WB.canvasBusy || (prop !== 'color' && prop !== 'fill') || !hex) return
    var patch = {}
    patch[prop] = hex
    canvasOps([{ op: 'update', id: o.id, patch: patch }])
  }

  var CANVAS_CSS_FONT = { sans: 'system-ui, Arial, sans-serif', serif: 'Georgia, "Times New Roman", serif', mono: 'ui-monospace, Consolas, monospace' }

  /** Szoveg szerkesztese HELYBEN: egy szovegmezo kerul az elem helyere, ugyanazzal a betumerettel es
   *  szinnel, mint amit a lapon latsz. Enter = uj sor, Ctrl+Enter vagy kattintas mellé = kesz, Esc = elvet. */
  function canvasEditText(id) {
    if (archived() || WB.canvasBusy || typeof document.querySelector !== 'function') return
    var o = canvasObject(id)
    var doc = (WB.canvas && WB.canvas.exists && WB.canvas.canvas) || null
    if (!o || o.type !== 'text' || !doc) return
    var layer = document.querySelector('.wb-can-layer')
    if (!layer || typeof layer.getBoundingClientRect !== 'function' || typeof document.createElement !== 'function') return
    var rect = layer.getBoundingClientRect()
    // Meret nelkul nem tudjuk a betumeretet a lapra szamolni: inkabb nem nyitjuk meg.
    if (!rect.width) return
    WB.canvasSel = id
    WB.canvasEditId = id
    // NEM rajzoljuk ujra a lapot (a kep ujratoltodne): csak a lebego eszkoztar tunik el, amig irsz.
    var fl = typeof document.querySelector === 'function' ? document.querySelector('[data-wb-float]') : null
    if (fl && typeof fl.remove === 'function') fl.remove()
    var k = rect.width / doc.width
    var ta = document.createElement('textarea')
    ta.className = 'wb-can-edit'
    ta.value = o.text || ''
    ta.setAttribute('aria-label', t('workbench.canvas.edit_text_aria'))
    ta.setAttribute('data-wb-edit', id)
    ta.style.cssText = 'position:absolute;left:' + (Math.round((10000 * o.x) / doc.width) / 100) + '%;top:' + (Math.round((10000 * o.y) / doc.height) / 100) + '%;'
      + 'width:' + (Math.round((10000 * o.width) / doc.width) / 100) + '%;height:' + (Math.round((10000 * o.height) / doc.height) / 100) + '%;'
      + 'font-size:' + (o.fontSize * k) + 'px;line-height:1.25;color:' + (o.color || '#111') + ';text-align:' + (o.align || 'left') + ';'
      + 'font-weight:' + (o.bold ? '700' : '400') + ';font-style:' + (o.italic ? 'italic' : 'normal') + ';font-family:' + (CANVAS_CSS_FONT[o.font] || CANVAS_CSS_FONT.sans) + ';'
      + (o.rotation ? 'transform:rotate(' + o.rotation + 'deg);' : '')
    var done = false
    function finish(commit) {
      if (done) return
      done = true
      WB.canvasEditId = null
      var val = ta.value
      if (typeof ta.remove === 'function') ta.remove()
      if (commit && val.trim() && val !== (o.text || '')) canvasOps([{ op: 'update', id: id, patch: { text: val } }])
      else render()
    }
    ta.addEventListener('keydown', function (ev) {
      if (ev.key === 'Escape') { ev.preventDefault(); finish(false) }
      else if (ev.key === 'Enter' && (ev.ctrlKey || ev.metaKey)) { ev.preventDefault(); finish(true) }
      ev.stopPropagation()
    })
    ta.addEventListener('blur', function () { finish(true) })
    layer.appendChild(ta)
    if (typeof ta.focus === 'function') ta.focus()
    if (typeof ta.select === 'function') ta.select()
  }

  document.addEventListener('dblclick', function (e) {
    if (!WB.open || archived() || !e.target || typeof e.target.closest !== 'function') return
    var boxEl = e.target.closest('[data-wb-box]')
    if (!boxEl) return
    var o = canvasObject(boxEl.getAttribute('data-wb-box'))
    if (o && o.type === 'text') { if (typeof e.preventDefault === 'function') e.preventDefault(); canvasEditText(o.id) }
  })

  // Enter vagy F2 a kijelolt szoveg-dobozon: szerkesztes (billentyuvel is elerheto).
  document.addEventListener('keydown', function (e) {
    if (!WB.open || archived() || !e.target || typeof e.target.closest !== 'function') return
    if (e.key !== 'Enter' && e.key !== 'F2') return
    var boxEl = e.target.closest('[data-wb-box]')
    if (!boxEl) return
    var o = canvasObject(boxEl.getAttribute('data-wb-box'))
    if (o && o.type === 'text') { e.preventDefault(); canvasEditText(o.id) }
  })

  // A Rétegek fül Formázás doboza: egy mező = egy `update`.
  document.addEventListener('change', function (e) {
    var el = e.target
    if (!el || typeof el.getAttribute !== 'function' || el.getAttribute('data-wb-act') !== 'fr-fmt') return
    frFormatChange(el)
  })

  // Side-by-side translation: remember the picked language (the panel is redrawn without the page).
  document.addEventListener('change', function (e) {
    var el = e.target
    if (!el || typeof el.getAttribute !== 'function' || !el.getAttribute('data-wb-tw-lang')) return
    var tw = twState()
    tw.lang = el.value; tw.note = ''; tw.failed = []
    writePref('wb.tw.lang', tw.lang)
    twEnsureLoaded()
    twRefresh()
  })

  // A szinvalasztok (szoveg-szin, kitoltes): a valasztas elengedesekor megy a muvelet.
  document.addEventListener('change', function (e) {
    var el = e.target
    if (!el || typeof el.getAttribute !== 'function') return
    var a = el.getAttribute('data-wb-act')
    if (a !== 'can-float-color' && a !== 'can-float-fill') return
    canvasFloatColor(a === 'can-float-color' ? 'color' : 'fill', el.value)
  })

  /** Kep a lapra: egy fajl a lapra HUZVA vagy a vagolapbol beillesztve. A fajl a projekt mappajaba kerul
   *  (ott keresi a felhasznalo), a lapra pedig egy kep-elem, a leejtes helyen. */
  function canvasDropImage(file, clientX, clientY, uploadOnly) {
    if (!file || !/^image\//.test(file.type || '')) { window.showToast(t('workbench.canvas.drop_not_image')); return }
    if (!WB.selectedId || WB.partBusy || WB.canvasBusy || archived()) return
    var doc = (WB.canvas && WB.canvas.exists && WB.canvas.canvas) || null
    if (!doc) return
    var layer = typeof document.querySelector === 'function' ? document.querySelector('.wb-can-layer') : null
    var rect = layer && typeof layer.getBoundingClientRect === 'function' ? layer.getBoundingClientRect() : null
    var cx = doc.width / 2
    var cy = doc.height / 2
    if (rect && rect.width && clientX != null) {
      cx = ((clientX - rect.left) / rect.width) * doc.width
      cy = ((clientY - rect.top) / rect.height) * doc.height
    }
    function place(nw, nh) {
      var w = Math.round(doc.width * 0.4)
      var h = Math.round(w * (nh && nw ? nh / nw : 0.75))
      var maxH = Math.round(doc.height * 0.9)
      if (h > maxH) { w = Math.round(w * maxH / h); h = maxH }
      var x = Math.round(Math.min(Math.max(cx - w / 2, 0), Math.max(doc.width - w, 0)))
      var y = Math.round(Math.min(Math.max(cy - h / 2, 0), Math.max(doc.height - h, 0)))
      uploadAndPlace(file, { x: x, y: y, width: w, height: h }, uploadOnly)
    }
    var natural = function () { place(0, 0) }
    if (typeof Image === 'function' && typeof URL !== 'undefined' && URL.createObjectURL) {
      var img = new Image()
      var u = URL.createObjectURL(file)
      img.onload = function () { try { URL.revokeObjectURL(u) } catch (_e) { /* mindegy */ } place(img.naturalWidth, img.naturalHeight) }
      img.onerror = function () { try { URL.revokeObjectURL(u) } catch (_e) { /* mindegy */ } natural() }
      img.src = u
    } else natural()
  }

  function uploadAndPlace(file, box, uploadOnly) {
    WB.partBusy = true
    render()
    // A fajl a projekt mappajaba kerul, a rajz-elem pedig az utjara mutat. Itt NEM keszul uj verzio (nem
    // `new_version`): egy uj verzio a rajz mentetlen allapotat nem vinne magaval.
    var url = '/api/workbench/items/' + encodeURIComponent(WB.selectedId) + '/parts/image'
      + '?name=' + encodeURIComponent(file.name || 'kep.png')
      + '&type=' + encodeURIComponent(file.type || '')
      + '&lang=' + encodeURIComponent(window._lang || 'hu')
    fetch(url, { method: 'POST', body: file }).then(function (res) {
      return res.json().catch(function () { return null }).then(function (data) {
        WB.partBusy = false
        if (!res.ok || !data || !data.part || !data.part.asset_path) {
          render()
          window.showToast((data && data.message) || t('workbench.err.http', { status: res.status }))
          return
        }
        applyParts(data)
        // The panel upload only stores the file (Boss, TG 2402): it appears in the thumbnails and the
        // hand places it on the page when wanted.
        if (uploadOnly) { render(); window.showToast(t('workbench.fr.uploaded')); return }
        canvasOps([{ op: 'add', object: { type: 'image', src: data.part.asset_path, x: box.x, y: box.y, width: box.width, height: box.height, fit: 'contain' } }])
      })
    }).catch(function () {
      WB.partBusy = false
      render()
      window.showToast(t('workbench.err.network'))
    })
  }

  document.addEventListener('dragover', function (e) {
    if (!WB.open || !e.target || typeof e.target.closest !== 'function') return
    var stage = e.target.closest('[data-wb-stage]')
    if (!stage || !e.dataTransfer || !e.dataTransfer.types || (Array.prototype.indexOf.call(e.dataTransfer.types, 'Files') < 0 && Array.prototype.indexOf.call(e.dataTransfer.types, 'text/wb-image') < 0)) return
    e.preventDefault()
    e.stopImmediatePropagation()
    if (stage.classList) stage.classList.add('wb-can-stage-drop')
  })
  document.addEventListener('dragleave', function (e) {
    var stage = e.target && typeof e.target.closest === 'function' ? e.target.closest('[data-wb-stage]') : null
    if (stage && stage.classList) stage.classList.remove('wb-can-stage-drop')
  })
  document.addEventListener('drop', function (e) {
    if (!WB.open || !e.target || typeof e.target.closest !== 'function') return
    var stage = e.target.closest('[data-wb-stage]')
    if (!stage) return
    if (stage.classList) stage.classList.remove('wb-can-stage-drop')
    var f = e.dataTransfer && e.dataTransfer.files && e.dataTransfer.files[0]
    if (!f) {
      var psrc = ''
      try { psrc = (e.dataTransfer && e.dataTransfer.getData('text/wb-image')) || '' } catch (_e) { psrc = '' }
      if (psrc) { e.preventDefault(); e.stopImmediatePropagation(); frAddImage(psrc, e.clientX, e.clientY) }
      return
    }
    e.preventDefault()
    e.stopImmediatePropagation()
    canvasDropImage(f, e.clientX, e.clientY)
  })

  // Beillesztes (Ctrl+V): a vagolapon levo kep a lap kozepere kerul -- csak ha a lap latszik es nem
  // szovegmezo van fokuszban.
  document.addEventListener('paste', function (e) {
    if (!WB.open || archived() || typeof document.querySelector !== 'function' || !document.querySelector('[data-wb-stage]')) return
    var tg = e.target
    if (tg && (tg.tagName === 'TEXTAREA' || tg.tagName === 'INPUT')) return
    var items = e.clipboardData && e.clipboardData.items
    if (!items) return
    for (var i = 0; i < items.length; i++) {
      if (items[i].kind === 'file' && /^image\//.test(items[i].type || '')) {
        var f = items[i].getAsFile()
        if (f) { e.preventDefault(); e.stopImmediatePropagation(); canvasDropImage(f, null, null); return }
      }
    }
  })

  // Kattintas az ures lapra: nincs kijeloles (a lebego eszkoztar eltunik).
  document.addEventListener('pointerdown', function (e) {
    if (!WB.open || !WB.canvasSel || !e.target || typeof e.target.closest !== 'function') return
    var t0 = e.target
    if (t0.closest('[data-wb-box]') || t0.closest('[data-wb-float]') || t0.closest('textarea')) return
    if (t0.closest('[data-wb-stage]')) { WB.canvasSel = null; render() }
  })

  // Az Egyszeru nezet kerete: nagyitas-csuszka, feltoltes a panelrol, kep huzasa a panelrol a lapra.
  document.addEventListener('input', function (e) {
    if (!e.target || e.target.id !== 'wbFrZoom') return
    var v = Number(e.target.value) || 100
    WB.frZoom = v
    frZoomSave(v)
    var scs = typeof document.querySelectorAll === 'function' ? document.querySelectorAll('.wb-fr-scroll, .wb-fr-fixed') : []
    for (var zi = 0; zi < scs.length; zi++) scs[zi].style.setProperty('--wb-zoom', String(v / 100))
    var lbl = typeof document.querySelector === 'function' ? document.querySelector('.wb-fr-zoomval') : null
    if (lbl && 'textContent' in lbl) lbl.textContent = v + '%'
  })
  document.addEventListener('change', function (e) {
    if (!e.target || e.target.id !== 'wbFrUpload') return
    var list = e.target.files
    var hasCanvas = !!(WB.canvas && WB.canvas.exists && WB.canvas.canvas)
    // A picture on a canvas item is kept as a picture part; every other file (and any file of a document, which
    // has no canvas) becomes a material in the Uploads folder. Before, the document case did nothing at all
    // (Boss, TG 2883).
    if (list && list.length === 1 && hasCanvas && isImageFile(list[0])) canvasDropImage(list[0], null, null, true)
    else if (list && list.length) uploadFiles(list, 'frassets')
    try { e.target.value = '' } catch (_e) { /* regi bongeszo: nem baj */ }
  })
  document.addEventListener('dragstart', function (e) {
    var th = e.target && typeof e.target.closest === 'function' ? e.target.closest('[data-wb-drag-img]') : null
    if (th && e.dataTransfer) { try { e.dataTransfer.setData('text/wb-image', th.getAttribute('data-wb-src') || ''); e.dataTransfer.effectAllowed = 'copy' } catch (_e) { /* nem baj */ } }
    var tf = !th && e.target && typeof e.target.closest === 'function' ? e.target.closest('[data-wb-drag-file]') : null
    if (tf && e.dataTransfer) {
      // #521 (Boss TG 8564): a file-list row carries its path in the data-wb-drag-file value itself (a tile has the
      // flag "1" and the path in data-wb-src) -- before, the row wrote an EMPTY path and the page drop did nothing.
      var tfRel = tf.getAttribute('data-wb-src') || ''
      if (!tfRel) { var tfv = tf.getAttribute('data-wb-drag-file') || ''; if (tfv && tfv !== '1') tfRel = tfv }
      try { e.dataTransfer.setData('text/wb-file', tfRel); e.dataTransfer.effectAllowed = 'copyMove' } catch (_e) { /* nem baj */ }
    }
  })

  // TG 1854: the overview's card rows open with Enter/Space too, not only a click.
  document.addEventListener('keydown', function (e) {
    if (!WB.open || (e.key !== 'Enter' && e.key !== ' ') || !e.target || typeof e.target.closest !== 'function') return
    var row = e.target.closest('[data-wb-act="card-open"]')
    if (!row) return
    e.preventDefault()
    openCard(row.getAttribute('data-wb-card'))
  })

  // Nyilbillentyuk: eger nelkul is mozgathato az elem (Shift = nagyobb lepes).
  // Ez ugyanaz a `move` muvelet, amit az agent is kuldene.
  document.addEventListener('keydown', function (e) {
    if (!WB.open || WB.canvasBusy || archived() || !e.target) return
    if (typeof e.target.closest !== 'function') return
    var boxEl = e.target.closest('[data-wb-box]')
    if (!boxEl) return
    var step = e.shiftKey ? 50 : 10
    var dx = 0
    var dy = 0
    if (e.key === 'ArrowLeft') dx = -step
    else if (e.key === 'ArrowRight') dx = step
    else if (e.key === 'ArrowUp') dy = -step
    else if (e.key === 'ArrowDown') dy = step
    else return
    if (typeof e.preventDefault === 'function') e.preventDefault()
    WB.canvasSel = boxEl.getAttribute('data-wb-box')
    canvasOps([{ op: 'move', id: WB.canvasSel, dx: dx, dy: dy }])
  })

  // Ctrl+Z / Ctrl+Y (Macen Cmd, es a Cmd+Shift+Z is ujra) a rajzon (K-2.1).
  // Szovegmezoben NEM: ott a bongeszo sajat visszavonasa a helyes (a felig
  // begepelt szoveg), nem a rajz utolso lepese.
  document.addEventListener('keydown', function (e) {
    if (!WB.open || !(e.ctrlKey || e.metaKey) || e.altKey) return
    var k = String(e.key || '').toLowerCase()
    if (k !== 'z' && k !== 'y' && k !== 'c' && k !== 'v' && k !== 'd') return
    var c = WB.canvas
    if (!c || !c.exists || c.current === false || !WB.selectedId) return
    var tg = e.target
    var tag = tg && tg.tagName ? String(tg.tagName).toUpperCase() : ''
    if (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || (tg && tg.isContentEditable)) return
    // Csak ha a rajz lathato: mas szerkesztonel a Ctrl+Z nem a rajzrol szol.
    var el = root()
    if (!el || String(el.innerHTML || '').indexOf('wb-can-tools') < 0) return
    if (k === 'c' || k === 'v' || k === 'd') {
      // Masolas (K-2.5): Ctrl+C a kijelolt elemet jegyzi meg, Ctrl+V masolatot
      // tesz le belole (akarhanyszor), Ctrl+D rogton duplikal. Kijelolt elem
      // nelkul a bongeszo sajat masolasa marad (pl. egy kijelolt szovegre).
      var sel = WB.canvasSel && canvasObject(WB.canvasSel) ? WB.canvasSel : null
      if (k === 'c') {
        if (!sel) return
        if (typeof window.getSelection === 'function' && String(window.getSelection() || '')) return
        WB.canvasClip = sel
        if (typeof e.preventDefault === 'function') e.preventDefault()
        return
      }
      var src = k === 'v' ? WB.canvasClip : sel
      if (!src || !canvasObject(src) || archived()) return
      if (typeof e.preventDefault === 'function') e.preventDefault()
      canvasOps([{ op: 'duplicate', id: src }])
      return
    }
    if (typeof e.preventDefault === 'function') e.preventDefault()
    canvasStep(k === 'y' || e.shiftKey ? 'redo' : 'undo')
  })

  // #533: Ctrl+Z / Ctrl+Y (Cmd+Shift+Z is ujra) a dokumentum-lapon. A lap sajat mezoiben (a begepelt, meg el nem
  // mentett szoveg is) a lap lepese hat: elobb elmentjuk, amit a kurzor melletti mezo tartalmaz, es az az egy
  // lepes vonodik vissza -- nem betunkent. Mas beviteli mezoben (chat, kereso) a bongeszo sajat visszavonasa marad.
  document.addEventListener('keydown', function (e) {
    if (e.defaultPrevented || !WB.open || e.isComposing || !(e.ctrlKey || e.metaKey) || e.altKey) return
    var k = String(e.key || '').toLowerCase()
    if (k !== 'z' && k !== 'y') return
    var it = WB.detail && WB.detail.item
    if (!WB.selectedId || !it || archived() || !docPageOpen(it)) return
    var tg = e.target
    var inPage = !!(tg && typeof tg.closest === 'function' && tg.closest('[data-wb-dp], .wb-dp-page'))
    var tag = tg && tg.tagName ? String(tg.tagName).toUpperCase() : ''
    if (!inPage && (tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT' || (tg && tg.isContentEditable))) return
    if (!document.querySelector('.wb-dp-page')) return
    e.preventDefault()
    docStep(k === 'y' || e.shiftKey ? 'redo' : 'undo')
  })

  // A gomb nem veheti el a fokuszt a lap mezojetol: a begepelt szoveg a lepeshez tartozik (dpFlush menti).
  document.addEventListener('mousedown', function (e) {
    if (e.target && typeof e.target.closest === 'function' && e.target.closest('[data-wb-step]')) e.preventDefault()
  }, true)

  // A bevitel erteket allapotban tartjuk: a chat-sav ujrarajzolasa (streameles
  // kozben soronkent) kulonben eltorolne a felig beirt mondatot.
  document.addEventListener('input', function (e) {
    if (!WB.open || !e.target) return
    if (e.target.id === 'wbChatInput') WB.chatDraft = e.target.value
    if (e.target.id === 'wbIntakeText') WB.intakeDraft = e.target.value
    if (e.target.id === 'wbIntakeName') WB.intakeName = e.target.value
    if (e.target.id === 'wbIntakePlatform' || e.target.id === 'wbTplPlatform') {
      WB.intakePlatform = e.target.value
      // #493: the new-item form shows both pickers at once; they share one choice, so the other one follows.
      var twin = document.getElementById(e.target.id === 'wbTplPlatform' ? 'wbIntakePlatform' : 'wbTplPlatform')
      if (twin) twin.value = e.target.value
    }
    if (e.target.id === 'wbCanAiText' && WB.canvasAi) WB.canvasAi.text = e.target.value
    if (e.target.id === 'wbRedactTerms' && WB.redact) WB.redact.terms = e.target.value
    if (/^wbBrand/.test(String(e.target.id || '')) && WB.brandOpen) brandSyncDraft()
  })

  // Enter kuld, Shift+Enter uj sort ir. (Telefonon a gomb marad a fo ut.)
  // A szerkeszto tartalma az ALLAPOTBAN el, nem csak a mezoben: egy kozben
  // erkezo ujrarajzolas (attekinto, elonezet, lista) kulonben visszairna az
  // eredeti szoveget, es a begepelt munka elveszne.
  document.addEventListener('input', function (e) {
    if (!WB.open || !e.target) return
    if (e.target.id === 'wbCmpSlider' && WB.compare) {
      var pos = Math.max(0, Math.min(100, Number(e.target.value) || 0))
      WB.compare.pos = pos
      // Csak a ket stilus valtozik -- a kepet nem rajzoljuk ujra huzas kozben.
      var top = document.getElementById('wbCmpTop')
      if (top && top.style) top.style.clipPath = 'inset(0 ' + (100 - pos) + '% 0 0)'
      var line = document.getElementById('wbCmpLine')
      if (line && line.style) line.style.left = pos + '%'
      return
    }
    if ((e.target.id === 'wbSendTo' || e.target.id === 'wbSendSubject' || e.target.id === 'wbSendMessage') && WB.selectedId) {
      var ss = sendState()
      if (!ss || ss.result) { ss = { itemId: WB.selectedId, draft: {} }; WB.send = ss }
      ss.draft = readSendDraft()
      return
    }
    if (WB.table && tableCellInput(e.target.id, e.target.value)) return
    if (WB.img && /^wbImg/.test(String(e.target.id || '')) && imgField(e.target.id, e.target)) return
    if (e.target.id === 'wbTextEdit' && WB.textEdit) { WB.textEdit.value = e.target.value; updateMdLive(e.target.value); trMarkStale() }
    else if (e.target.id === 'wbPartText' && WB.partEdit) WB.partDraft = { id: WB.partEdit, value: e.target.value }
  })

  // Kozossegi poszt: a kivagas huzasa a kepkereten. Csak a focus szazalekot
  // allitja (object-position), rajzolas nelkul -- a letoltes ugyanezt hasznalja.
  document.addEventListener('pointerdown', function (e) {
    if (!WB.open || !WB.post || !e.target || !e.target.closest) return
    var frame = e.target.closest('[data-wb-post-frame]')
    if (!frame) return
    var img = frame.querySelector('img')
    if (!img) return
    e.preventDefault()
    var st = WB.post
    var sx = e.clientX, sy = e.clientY, fx0 = st.fx, fy0 = st.fy
    var rect = frame.getBoundingClientRect()
    function move(ev) {
      // Huzas jobbra = a kep jobbra megy = a kivagas balra (kisebb x).
      st.fx = Math.max(0, Math.min(100, fx0 - (ev.clientX - sx) / Math.max(1, rect.width) * 100))
      st.fy = Math.max(0, Math.min(100, fy0 - (ev.clientY - sy) / Math.max(1, rect.height) * 100))
      img.style.objectPosition = st.fx + '% ' + st.fy + '%'
    }
    function up() { document.removeEventListener('pointermove', move); document.removeEventListener('pointerup', up) }
    document.addEventListener('pointermove', move)
    document.addEventListener('pointerup', up)
  })

  // Ctrl+S / Cmd+S a szerkesztoben: mentes (uj verzio) -- a bongeszo sajat
  // "oldal mentese" ablaka helyett, ami itt senkinek nem kell.
  document.addEventListener('keydown', function (e) {
    if (!WB.open || !e.target || !(e.ctrlKey || e.metaKey) || String(e.key).toLowerCase() !== 's') return
    var id = e.target.id
    if (/^wbCell_/.test(String(id || '')) && WB.table) {
      if (typeof e.preventDefault === 'function') e.preventDefault()
      saveTable()
      return
    }
    if (id !== 'wbTextEdit' && id !== 'wbPartText' && id !== 'wbPartNewText') return
    if (typeof e.preventDefault === 'function') e.preventDefault()
    if (id === 'wbTextEdit') saveTextEdit()
    else if (id === 'wbPartText' && WB.partEdit) savePart(WB.partEdit)
    else if (id === 'wbPartNewText') addTextPart()
  })

  // Kepszerkeszto: kattintas az EREDMENYEN = a hatter egy pontja (arasztas innen).
  document.addEventListener('click', function (e) {
    if (!WB.open || !e.target || typeof e.target.closest !== 'function') return
    var pick = e.target.closest('[data-wb-img-pick]')
    var st = imgState()
    if (!pick || !st || !st.bg.pick || typeof pick.getBoundingClientRect !== 'function') return
    var rect = pick.getBoundingClientRect()
    if (!rect.width || !rect.height) return
    st.bg.seeds.push({
      x: Math.max(0, Math.min(1, (e.clientX - rect.left) / rect.width)),
      y: Math.max(0, Math.min(1, (e.clientY - rect.top) / rect.height)),
    })
    st.dirty = true
    render()
    imgRefresh(false)
  })

  document.addEventListener('pointerdown', function (e) {
    if (!WB.open || !e.target || typeof e.target.closest !== 'function') return
    var h = e.target.closest('[data-wb-crop]')
    var st = imgState()
    var stage = document.getElementById('wbImgStage')
    if (!h || !st || !st.crop || !stage || typeof stage.getBoundingClientRect !== 'function') return
    if (typeof e.preventDefault === 'function') e.preventDefault()
    imgDrag = {
      mode: h.getAttribute('data-wb-crop'), x0: e.clientX, y0: e.clientY, rect: stage.getBoundingClientRect(),
      crop: { x: st.crop.x, y: st.crop.y, w: st.crop.w, h: st.crop.h }, last: null,
    }
    if (h.setPointerCapture && e.pointerId != null) { try { h.setPointerCapture(e.pointerId) } catch (_e) { /* nem baj */ } }
  })

  document.addEventListener('pointermove', function (e) {
    if (!imgDrag) return
    var st = imgState()
    if (!st) { imgDrag = null; return }
    var c = imgDragApply(imgDrag, e.clientX, e.clientY)
    if (!c) return
    imgDrag.last = c
    var box = document.querySelector('[data-wb-crop="move"]')
    var saved = st.crop
    st.crop = c
    if (box && box.setAttribute) box.setAttribute('style', imgCropStyle(st))
    st.crop = saved
  })

  function imgDragEnd(commit) {
    if (!imgDrag) return
    var st = imgState()
    var c = imgDrag.last
    imgDrag = null
    if (!st || !c || !commit) { render(); return }
    st.crop = c
    st.aspect = IMG_ASPECTS[st.aspect] ? st.aspect : 'free'
    st.outW = c.w
    st.bg.seeds = []
    st.dirty = true
    render()
    imgRefresh(false)
  }
  document.addEventListener('pointerup', function () { imgDragEnd(true) })
  document.addEventListener('pointercancel', function () { imgDragEnd(false) })

  // Tablazat: Enter = a lenti cella (mint az Excelben), Shift+Enter = a fenti.
  document.addEventListener('keydown', function (e) {
    if (!WB.open || !e.target || !WB.table || e.key !== 'Enter') return
    var m = /^wbCell_(\d+)_(\d+)$/.exec(String(e.target.id || ''))
    if (!m) return
    if (typeof e.preventDefault === 'function') e.preventDefault()
    var sh = tableSheet()
    var r = Number(m[1]) + (e.shiftKey ? -1 : 1)
    if (!sh || r < 0 || r >= sh.rows.length) return
    WB.table.sel = { r: r, c: Number(m[2]) }
    var next = document.getElementById('wbCell_' + r + '_' + m[2])
    if (!next) { WB.table.page = Math.floor(r / TABLE_PAGE); render(); next = document.getElementById('wbCell_' + r + '_' + m[2]) }
    if (next && typeof next.focus === 'function') next.focus()
  })

  document.addEventListener('focusin', function (e) {
    if (!WB.open || !WB.table || !e.target) return
    var m = /^wbCell_(\d+)_(\d+)$/.exec(String(e.target.id || ''))
    if (m) WB.table.sel = { r: Number(m[1]), c: Number(m[2]) }
  })

  document.addEventListener('keydown', function (e) {
    if (!WB.open || !e.target || e.target.id !== 'wbChatInput') return
    if (e.key === 'Enter' && !e.shiftKey) {
      if (typeof e.preventDefault === 'function') e.preventDefault()
      WB.chatDraft = e.target.value
      if (WB.dict) dictStop()
      sendChat()
    }
  })

  document.addEventListener('change', function (e) {
    if (!WB.open || !e.target) return
    if (WB.img && /^wbImg(CapPos|CapColor|CapBand)$/.test(String(e.target.id || '')) && imgField(e.target.id, e.target)) return
    if (/^wbVt(Zoom|PanX|PanY)$/.test(String(e.target.id || ''))) {
      var zv = function (id, d) { var el = document.getElementById(id); return el ? Number(el.value) : d }
      var zz = zv('wbVtZoom', 1)
      vtOps([{ op: 'setClipFrame', id: e.target.getAttribute('data-wb-id'), zoom: zz, panX: zz > 1 ? zv('wbVtPanX', 0) : 0, panY: zz > 1 ? zv('wbVtPanY', 0) : 0 }])
      return
    }
    if (e.target.id === 'wbVtRot' || e.target.id === 'wbVtFlip') {
      vtOps([{ op: 'setClipOrient', id: e.target.getAttribute('data-wb-id'), rotate: Number(document.getElementById('wbVtRot').value), flip: document.getElementById('wbVtFlip').value }])
      return
    }
    if (e.target.id === 'wbVtFadeIn' || e.target.id === 'wbVtFadeOut') {
      vtOps([{ op: 'setClipFade', id: e.target.getAttribute('data-wb-id'), in: Number(document.getElementById('wbVtFadeIn').value), out: Number(document.getElementById('wbVtFadeOut').value) }])
      return
    }
    if (e.target.id === 'wbVtStab') { vtOps([{ op: 'setStabilize', id: e.target.getAttribute('data-wb-id'), on: !!e.target.checked }]); return }
    if (e.target.id === 'wbVtLook') { vtOps([{ op: 'setClipLook', id: e.target.getAttribute('data-wb-id'), look: e.target.value }]); return }
    if (e.target.id === 'wbVtSpeed') { vtOps([{ op: 'setSpeed', id: e.target.getAttribute('data-wb-id'), speed: Number(e.target.value) }]); return }
    if (e.target.id === 'wbVtTransType' || e.target.id === 'wbVtTransDur') { frVtTransApply(); return }
    if (e.target.id === 'wbPostPlatform') { postState().platform = postPlatform(e.target.value).id; postState().more = false; render(); return }
    if (e.target.id === 'wbCanPlatform') { WB.canvasPlatformPick = e.target.value; render(); return }
    if (e.target.id === 'wbSwitch') {
      selectItem(e.target.value)
      return
    }
    // MELLEKLETEK szamozasa (#441, K-1.18): a szerver a szovegbeli hivatkozasokat is atirja.
    if (e.target.id === 'wbPdRole') { WB.pdAddRole = e.target.value; render(); return }
    if (e.target.id === 'wbAnnexScheme') { outlineCall('PATCH', '/settings', { annex_scheme: e.target.value }); return }
    if (e.target.id === 'wbAnnexMode') { outlineCall('PATCH', '/settings', { annex_mode: e.target.value }); return }
    // CELBIROSAG-PROFIL (#441, K-1.36)
    if (e.target.id === 'wbCourtProfile') { courtCall('PUT', '', { profile_id: e.target.value || null }); return }
    if (e.target.id === 'wbCourtMaxAge') { courtCall('PUT', '/settings', { max_age_days: Number(e.target.value) }, function () { window.showToast(t('workbench.court.settings_saved')) }); return }
    if (e.target.id === 'wbAnnexPrefix') {
      var px = String(e.target.value || '').trim().toUpperCase()
      if (/^[A-Z]{1,2}$/.test(px)) outlineCall('PATCH', '/settings', { annex_prefix: px })
      else window.showToast(t('workbench.annex.prefix_bad'))
      return
    }
    if ((e.target.id === 'wbCmpLeft' || e.target.id === 'wbCmpRight') && WB.compare) {
      if (e.target.id === 'wbCmpLeft') WB.compare.left = e.target.value
      else WB.compare.right = e.target.value
      render()
      loadCompareSide(e.target.value)
      return
    }
    if (e.target.id === 'wbTreeUpload') {
      treeUploadStart(e.target.files)
      try { e.target.value = '' } catch (_e) { /* old browser: harmless */ }
      return
    }
    if (e.target.id === 'wbTreeUpDest') { if (WB.treeUp) WB.treeUp.dest = e.target.value; return }
    if (e.target.id === 'wbUploadNew') {
      var picked = e.target.files
      if (picked && picked.length) uploadFiles(picked, 'new')
      try { e.target.value = '' } catch (_e) { /* regi bongeszo: nem baj */ }
      return
    }
    if (e.target.getAttribute && e.target.getAttribute('data-wb-annex-browse')) {
      var af = []
      for (var ai = 0; e.target.files && ai < e.target.files.length; ai++) af.push(e.target.files[ai])
      try { e.target.value = '' } catch (_e) { /* regi bongeszo: nem baj */ }
      if (af.length) annexBrowseUpload(af)
      return
    }
    if (e.target.getAttribute && e.target.getAttribute('data-wb-vt-browse')) {
      var vf = e.target.files && e.target.files[0]
      try { e.target.value = '' } catch (_e) { /* regi bongeszo: nem baj */ }
      if (vf) vtBrowseUpload(vf)
      return
    }
    if (e.target.id === 'wbAssetUpload' || e.target.id === 'wbChatAssetUpload') {
      var att = e.target.files
      // The chat's paperclip asks first (reference for the agent / upload into the item); the Materials box button keeps the item folder.
      if (att && att.length) uploadFiles(att, e.target.id === 'wbChatAssetUpload' ? 'chat' : 'assets')
      try { e.target.value = '' } catch (_e) { /* regi bongeszo: nem baj */ }
      return
    }
    if (e.target.id === 'wbSharedUpload') {
      var sf = e.target.files
      if (sf && sf.length) uploadShared(sf)
      try { e.target.value = '' } catch (_e) { /* regi bongeszo: nem baj */ }
      return
    }
    if (e.target.id === 'wbDocUpload') {
      var docs = e.target.files
      if (docs && docs.length) uploadDocumentVersion(docs[0])
      return
    }
    if (e.target.id === 'wbPartImage') {
      var files = e.target.files
      if (files && files.length) uploadImagePart(files[0])
      return
    }
    // Verzio-valaszto az elonezethez: a REGI verziot is meg lehet nezni.
    if (e.target.id === 'wbPreviewVersion' && WB.selectedId) {
      WB.previewVersion = e.target.value || null
      loadPreview(WB.selectedId, WB.previewVersion)
    }
  })

  // Item rows can be dragged onto a folder row (files the item into it).
  document.addEventListener('dragstart', function (e) {
    if (!WB.open || !e.target || !e.target.closest) return
    var row = e.target.closest('[data-wb-drag-item]')
    if (!row || !e.dataTransfer) return
    WB.dragItem = row.getAttribute('data-wb-drag-item')
    try { e.dataTransfer.setData('text/x-wb-item', WB.dragItem); e.dataTransfer.effectAllowed = 'move' } catch (_e) { /* nem baj */ }
  })
  document.addEventListener('dragend', function () { WB.dragItem = null; WB.dragFolder = null; WB.dragFile = null })
  // #492: a file row dragged onto a folder row: a loose file moves there, a work item's own file is only
  // offered as a copy (moveFilesToFolder asks). A ticked file drags every ticked one with it.
  document.addEventListener('dragstart', function (e) {
    if (!WB.open || WB.dragItem || WB.dragFolder || !e.target || !e.target.closest || !e.dataTransfer) return
    var row = e.target.closest('[data-wb-drag-file]')
    if (!row) return
    // #537: only the project box's own file rows may be moved by dropping them on a folder row. A row of the item's
    // assets or of the shared Kozos anyagok folder (and a tile) is draggable onto the PAGE only; it must never move.
    if (row.getAttribute('data-wb-ctx-file') === null) return
    WB.dragFile = row.getAttribute('data-wb-drag-file')
    try { e.dataTransfer.setData('text/x-wb-file', WB.dragFile); e.dataTransfer.effectAllowed = 'copyMove' } catch (_e) { /* nem baj */ }
  })
  document.addEventListener('dragover', function (e) {
    if (!WB.open || !WB.dragFile || !e.target || !e.target.closest) return
    if (e.target.closest('[data-wb-drop-folder]')) { e.preventDefault(); try { e.dataTransfer.dropEffect = isItemFile(WB.dragFile) ? 'copy' : 'move' } catch (_e) { /* nem baj */ } }
  })
  document.addEventListener('drop', function (e) {
    if (!WB.open || !WB.dragFile || !e.target || !e.target.closest) return
    var z = e.target.closest('[data-wb-drop-folder]')
    if (!z) return
    e.preventDefault()
    var rel = WB.dragFile
    WB.dragFile = null
    var many = WB.fileSel && WB.fileSel[rel] && Object.keys(WB.fileSel).length > 1
    moveFilesToFolder(many ? '*' : rel, z.getAttribute('data-wb-drop-folder') || '\u0000box')
  })
  // A folder row dragged onto another folder row moves the folder with everything in it (TG 2478).
  document.addEventListener('dragstart', function (e) {
    if (!WB.open || WB.dragItem || !e.target || !e.target.closest || !e.dataTransfer) return
    var row = e.target.closest('[data-wb-drag-folder]')
    if (!row) return
    WB.dragFolder = row.getAttribute('data-wb-drag-folder')
    try { e.dataTransfer.setData('text/x-wb-folder', WB.dragFolder); e.dataTransfer.effectAllowed = 'move' } catch (_e) { /* nem baj */ }
  })
  document.addEventListener('dragover', function (e) {
    if (!WB.open || !WB.dragFolder || !e.target || !e.target.closest) return
    if (e.target.closest('[data-wb-drop-folder]')) { e.preventDefault(); try { e.dataTransfer.dropEffect = 'move' } catch (_e) { /* nem baj */ } }
  })
  document.addEventListener('drop', function (e) {
    if (!WB.open || !WB.dragFolder || !e.target || !e.target.closest) return
    var z = e.target.closest('[data-wb-drop-folder]')
    if (!z) return
    e.preventDefault()
    var f = WB.dragFolder
    WB.dragFolder = null
    var to = z.getAttribute('data-wb-drop-folder') || ''
    if (!to && z.getAttribute('data-wb-drop-box')) to = (WB.workFolders && WB.workFolders.box) || ''
    if (to && to !== f) moveFolder(f, to)
  })
  document.addEventListener('dragover', function (e) {
    if (!WB.open || !WB.dragItem || !e.target || !e.target.closest) return
    if (e.target.closest('[data-wb-drop-folder]')) { e.preventDefault(); try { e.dataTransfer.dropEffect = 'move' } catch (_e) { /* nem baj */ } }
  })
  document.addEventListener('drop', function (e) {
    if (!WB.open || !WB.dragItem || !e.target || !e.target.closest) return
    var z = e.target.closest('[data-wb-drop-folder]')
    if (!z) return
    e.preventDefault()
    var id = WB.dragItem
    WB.dragItem = null
    moveItemToFolder(id, z.getAttribute('data-wb-drop-folder') || '\u0000box')
  })

  // Behuzas: a bongeszo alapbol MEGNYITNA a fajlt (elhagyva a Munkapadot) --
  // ezt csak a Munkapadon belul akadalyozzuk meg, mashol nem szolunk bele.
  document.addEventListener('dragover', function (e) {
    if (!WB.open || !hasFiles(e) || !inWorkbench(e)) return
    e.preventDefault()
    if (e.dataTransfer) { try { e.dataTransfer.dropEffect = 'copy' } catch (_e) { /* nem baj */ } }
    setDragging(true)
  })
  document.addEventListener('dragleave', function (e) {
    if (!WB.open) return
    // Csak ha tenyleg kiment a Munkapadrol (a gyerek-elemek kozott is jon dragleave).
    if (!e.relatedTarget || !inWorkbench({ target: e.relatedTarget })) setDragging(false)
  })
  document.addEventListener('drop', function (e) {
    if (!WB.open || !inWorkbench(e)) return
    setDragging(false)
    if (!hasFiles(e)) return
    e.preventDefault()
    uploadFiles(e.dataTransfer.files, dropTarget(e))
  })
  // Beillesztes (Ctrl+V): kepernyokep, masolt fajl. Szoveg beillesztesebe
  // nem szolunk bele -- csak ha a vagolapon FAJL van.
  document.addEventListener('paste', function (e) {
    if (!WB.open) return
    var files = e && e.clipboardData && e.clipboardData.files
    if (!files || !files.length) return
    e.preventDefault()
    var inChat = false
    try { inChat = !!(document.activeElement && document.activeElement.id === 'wbChatInput') } catch (_e) { inChat = false }
    uploadFiles(files, WB.selectedId && WB.detail ? (inChat ? 'chat' : 'item') : 'new')
  })

  // ---- dokumentum-lap: esemenyek (#462, 4. lepes) ---------------------------------------------

  function dpField(e) {
    // The page is one editing host: the event's target is the page, the field is where the cursor is.
    return dpCurrent() || (e.target && typeof e.target.closest === 'function' ? e.target.closest('[data-wb-dp]') : null)
  }

  document.addEventListener('click', function (e) {
    if (!WB.open || !e.target || typeof e.target.closest !== 'function') return
    if (e.target.closest('[data-wb-tbl-resize], .wb-dp-tbl-move, [data-wb-free-move]')) return
    var act = e.target.closest('[data-wb-act]')
    var a = act ? act.getAttribute('data-wb-act') : ''
    if (WB.docMenu && (!a || a.indexOf('dp-') !== 0) && !e.target.closest('.wb-dp-menu')) { WB.docMenu = null; if (!a) render() }
    if (!a || a.indexOf('dp-') !== 0) return
    e.preventDefault()
    var sid = act.getAttribute('data-wb-sec') || ''
    var bid = act.getAttribute('data-wb-block') || ''
    if (a === 'dp-add') dpMenuOpen('add', bid, sid)
    else if (a === 'dp-handle') dpMenuOpen('handle', bid, sid)
    else if (a === 'dp-tbl-edit') dpTblEdit(bid)
    else if (a === 'dp-img-align') dpImageSave(bid, null, act.getAttribute('data-wb-align'))
    else if (a === 'dp-img-mode') dpImageMode(bid, act.getAttribute('data-wb-mode'))
    else if (a === 'dp-tbl-align') dpTableAlign(bid, act.getAttribute('data-wb-align'))
    else if (a === 'dp-ins') dpInsert(sid, bid, act.getAttribute('data-wb-kind'))
    else if (a === 'dp-ins-section') dpInsertSection(sid)
    else if (a === 'dp-ins-sign') dpSignPicker(sid, bid)
    else if (a === 'dp-move') dpMoveStep(bid, Number(act.getAttribute('data-wb-dir')) || 0)
    else if (a === 'dp-del') dpDeleteBlock(bid)
    else if (a === 'dp-add-section') dpAddSection()
    else if (a === 'dp-outline-go') {
      var gt = document.getElementById(bid ? 'wbDpB_' + bid : 'wbDpS_' + sid)
      if (gt) { try { gt.scrollIntoView({ block: 'center', behavior: 'smooth' }) } catch (_e) { gt.scrollIntoView() } dpFocusRoot(); dpPlaceCaret(gt, 0) }
    }
    else if (a === 'dp-outline-toggle') {
      WB.dpOutline = !dpOutlineOn()
      try { window.localStorage.setItem('marveen.workbench.dpOutline', WB.dpOutline ? '1' : '0') } catch (er) { /* a convenience only */ }
      render()
    }
    else if (a === 'dp-pages-toggle') {
      WB.dpPagesOn = !dpPagesOn()
      writePref('marveen.workbench.dpSheets', WB.dpPagesOn ? '1' : '0')
      act.classList.toggle('is-on', WB.dpPagesOn)
      act.setAttribute('aria-pressed', WB.dpPagesOn ? 'true' : 'false')
      WB.dpPagesError = ''
      dpPagesPaint()
      if (WB.dpPagesOn) dpPagesLoad()
    }
  })

  // Mentes: az oldalbol kilepve az egesz oldal egy hivassal. Az ujrarajzolas altal okozott "kilepes" nem szamit.
  document.addEventListener('focusout', function (e) {
    if (!WB.open || WB.rendering) return
    var host = e.target && typeof e.target.closest === 'function' ? e.target.closest('.wb-dp-page') : null
    if (!host) return
    var to = e.relatedTarget
    if (to && typeof host.contains === 'function' && host.contains(to) && !(typeof to.closest === 'function' && to.closest('[data-wb-act]'))) return
    if (WB.dpDirty) dpPageSave()
    dpTblLeaveCheck()
  })

  document.addEventListener('input', function (e) {
    if (!WB.open || !e.target || typeof e.target.closest !== 'function') return
    if (e.target.closest('.wb-dp-page[contenteditable="true"]')) dpMarkDirty()
    // #649: the grid under an open table's lines follows what is typed.
    var tf = dpCurrent()
    var prev = tf && tf.parentElement ? tf.parentElement.querySelector('.wb-dp-tbl-prev') : null
    if (prev) {
      prev.innerHTML = dpTableGridRowsHtml(tf.innerText)
    }
  })

  // #562 (Boss TG 8922: "klikkelek a dokumentum vegere, es ott nem tudok elkezdeni irni"): a click on the empty part of
  // the sheet -- under the last line, or on the margin beside nothing -- puts the cursor at the end of the last writable
  // line, as a word processor does. A click on a line, a picture, a table or a button is left to its own handling.
  document.addEventListener('click', function (e) {
    if (!WB.open || WB.rendering || !e.target || typeof e.target.closest !== 'function') return
    var page = e.target.closest('.wb-dp-page[contenteditable="true"]')
    if (!page || e.target.closest('.wb-dp-edit, figure, table, button, a, input, select, [data-wb-act], [contenteditable="false"]')) return
    var lines = page.querySelectorAll('.wb-dp-edit[data-wb-dp="block"], .wb-dp-edit[data-wb-dp="new"]')
    if (!lines.length) return
    var last = lines[lines.length - 1]
    var box = typeof last.getBoundingClientRect === 'function' ? last.getBoundingClientRect() : null
    if (!box || e.clientY < box.bottom) return // beside or above a line: the browser already put the cursor there
    try { page.focus() } catch (_e) { /* nem baj */ }
    dpPlaceCaret(last, null)
  })

  /** The grid of a table block comes back when the cursor leaves its lines. */
  function dpTblLeaveCheck() {
    if (!WB.dpTblEdit) return
    var cur = dpCurrent()
    if (cur && cur.getAttribute('data-wb-block') === WB.dpTblEdit) return
    // Just opened and the cursor is nowhere yet (the click's own focus handling is still settling): not a leave.
    if (!cur && Date.now() - (WB.dpTblEditAt || 0) < 400) return
    var bid = WB.dpTblEdit
    dpFlush().then(function () {
      if (WB.dpTblEdit === bid) { WB.dpTblEdit = null; render() }
    })
  }

  /** A fresh paragraph row after `el`'s row, carrying `frag`'s content; the cursor goes to its start. */
  function dpSplitField(el) {
    var sel = window.getSelection()
    if (!sel || !sel.rangeCount) return null
    var r = sel.getRangeAt(0)
    if (!r.collapsed) r.deleteContents()
    var tail = document.createRange()
    tail.setStart(r.endContainer, r.endOffset)
    tail.setEnd(el, el.childNodes.length)
    var frag = tail.extractContents()
    var kind = el.getAttribute('data-wb-kind') || (findBlock(el.getAttribute('data-wb-block') || '') || {}).kind || 'paragraph'
    var nk = kind === 'list' ? 'list' : 'paragraph'
    var sid = el.getAttribute('data-wb-sec') || ''
    var row = el.closest('.wb-dp-row')
    var host = document.createElement('div')
    host.innerHTML = '<div class="wb-dp-row" data-wb-sec="' + escA(sid) + '">' + dpGutterHtml('', sid, 0, 0, false)
      + dpEditHtml('wb-dp-block wb-outline-kind-' + nk, '', 'data-wb-dp="block" data-wb-sec="' + escA(sid) + '" data-wb-kind="' + nk + '"', '', t('workbench.dp.block_ph'), t('workbench.dp.block_label'), false, null) + '</div>'
    var nrow = host.firstChild
    var nf = nrow.querySelector('[data-wb-dp]')
    nf.id = 'wbDpT_' + (++dpBlockSeq)
    // The paragraph's own look (alignment, spacing) carries on; a heading does not.
    var al = el.getAttribute('data-wb-align')
    if (al) { nf.setAttribute('data-wb-align', al); nf.classList.add('wb-dp-al-' + al) }
    var pf = dpPfmtOf(el)
    delete pf.h
    if (Object.keys(pf).length) { nf.setAttribute('data-wb-pfmt', JSON.stringify(pf)); nf.setAttribute('style', dpPfmtStyle(pf)) }
    if (nk === 'list' && el.classList.contains('wb-dp-numbered')) nf.classList.add('wb-dp-numbered')
    nf.appendChild(frag)
    if (row && row.parentNode) row.parentNode.insertBefore(nrow, row.nextSibling)
    else if (el.parentNode) el.parentNode.insertBefore(nrow, el.nextSibling)
    dpPlaceCaret(nf, 0)
    return nf
  }

  /** Neighbour fields in the page's order: `dir` -1 / +1; islands count as neighbours (they are not text). */
  function dpNeighbour(el, dir) {
    var rootEl = dpRoot()
    if (!rootEl) return null
    var all = rootEl.querySelectorAll('[data-wb-dp], [data-wb-img-block], [data-wb-tbl-block]')
    for (var i = 0; i < all.length; i++) if (all[i] === el) return all[i + dir] || null
    return null
  }

  /** The row of a field goes away (the paragraph is gone from the page); the cursor goes to `to`. */
  function dpDropRow(el) {
    var row = el.closest('.wb-dp-row')
    var host = row || el
    if (host.parentNode) host.parentNode.removeChild(host)
  }

  document.addEventListener('keydown', function (e) {
    if (!WB.open || e.isComposing) return
    var host = e.target && typeof e.target.closest === 'function' ? e.target.closest('.wb-dp-page[contenteditable="true"]') : null
    if (!host) return
    var el = dpCurrent()
    if (e.key === 'Escape') {
      WB.docMenu = null
      if (typeof host.blur === 'function') host.blur()
      return
    }
    if (!el) {
      if (e.key === 'Enter') e.preventDefault()
      return
    }
    var kind = el.getAttribute('data-wb-dp')
    var sid = el.getAttribute('data-wb-sec') || ''
    var isTable = el.classList.contains('wb-outline-kind-table')
    // #508: in a table block's lines Enter starts a new line, it does not split the block.
    if (e.key === 'Enter' && isTable) return
    if (e.key === 'Enter' && !e.shiftKey && !e.ctrlKey && !e.metaKey) {
      e.preventDefault()
      if (kind === 'sec') {
        // The title's Enter jumps to the first line below it (or makes one when the chapter is empty).
        var nx = dpNeighbour(el, 1)
        if (nx && /^(block|new)$/.test(nx.getAttribute('data-wb-dp') || '')) dpFocusField(nx, 0)
        else {
          var nrow = document.createElement('div')
          nrow.innerHTML = '<div class="wb-dp-row" data-wb-sec="' + escA(sid) + '">' + dpGutterHtml('', sid, 0, 0, false)
            + dpEditHtml('wb-dp-block wb-outline-kind-paragraph', '', 'data-wb-dp="block" data-wb-sec="' + escA(sid) + '" data-wb-kind="paragraph"', '', t('workbench.dp.block_ph'), t('workbench.dp.block_label'), false, null) + '</div>'
          var rowEl = nrow.firstChild
          var head = el.closest('.wb-dp-sechead')
          var after = head && head.parentNode ? head.nextElementSibling : null
          while (after && after.classList && after.classList.contains('wb-dp-secextra')) after = after.nextElementSibling
          if (head && head.parentNode) head.parentNode.insertBefore(rowEl, after)
          var nf0 = rowEl.querySelector('[data-wb-dp]')
          nf0.id = 'wbDpT_' + (++dpBlockSeq)
          dpFocusField(nf0, 0)
          dpMarkDirty()
        }
        return
      }
      // An empty list line + Enter leaves the list.
      if (!dpText(el) && (el.getAttribute('data-wb-kind') === 'list' || el.classList.contains('wb-outline-kind-list'))) {
        el.setAttribute('data-wb-kind', 'paragraph')
        el.classList.remove('wb-outline-kind-list', 'wb-dp-numbered')
        el.classList.add('wb-outline-kind-paragraph')
        dpMarkDirty()
        return
      }
      if (dpSplitField(el)) dpMarkDirty()
      return
    }
    var sel = window.getSelection()
    var collapsed = !!sel && sel.rangeCount > 0 && sel.isCollapsed
    if (e.key === 'Backspace' && collapsed && !e.ctrlKey && !e.metaKey && !e.altKey && dpCaret(el) === 0 && !isTable) {
      e.preventDefault()
      if (kind === 'sec') return
      var prev = dpNeighbour(el, -1)
      if (!dpText(el)) {
        // An empty line + Backspace: the paragraph goes, the cursor to the end of the one above.
        if (prev && /^(block|new)$/.test(prev.getAttribute('data-wb-dp') || '')) { dpDropRow(el); dpFocusField(prev, null); dpMarkDirty() }
        else if (prev && prev.getAttribute('data-wb-dp') === 'sec') { dpDropRow(el); dpFocusField(prev, null); dpMarkDirty() }
        return
      }
      if (prev && /^(block|new)$/.test(prev.getAttribute('data-wb-dp') || '') && !prev.classList.contains('wb-outline-kind-table')) {
        // Merge into the paragraph above: the cursor stays where the two met.
        var mark = document.createRange()
        mark.selectNodeContents(prev)
        var at = mark.toString().length
        while (el.firstChild) prev.appendChild(el.firstChild)
        dpDropRow(el)
        dpFocusField(prev, at)
        dpMarkDirty()
      }
      return
    }
    if (e.key === 'Delete' && collapsed && !e.ctrlKey && !e.metaKey && !e.altKey && !isTable && kind !== 'sec') {
      var tailR = document.createRange()
      tailR.selectNodeContents(el)
      tailR.setStart(sel.getRangeAt(0).endContainer, sel.getRangeAt(0).endOffset)
      if (tailR.toString().length > 0) return
      e.preventDefault()
      var nxt = dpNeighbour(el, 1)
      if (nxt && /^(block|new)$/.test(nxt.getAttribute('data-wb-dp') || '') && !nxt.classList.contains('wb-outline-kind-table')) {
        var m2 = document.createRange()
        m2.selectNodeContents(el)
        var at2 = m2.toString().length
        while (nxt.firstChild) el.appendChild(nxt.firstChild)
        dpDropRow(nxt)
        dpFocusField(el, at2)
        dpMarkDirty()
      }
    }
  })

  // ---- Word-szeru formazo eszkoztar (Boss TG 2803) ---------------------------------------------
  // A gomb nem veheti el a fokuszt (kijeloles) a szovegtol; a formazas a mezo tartalmaban van, a mentes
  // a mezobol kilepeskor a szokott uton megy.
  document.addEventListener('mousedown', function (e) {
    if (e.target && typeof e.target.closest === 'function' && e.target.closest('[data-wb-fmt]')) e.preventDefault()
  }, true)

  document.addEventListener('focusin', function (e) {
    var el = dpField(e)
    if (el && el.id && /^(block|new)$/.test(el.getAttribute('data-wb-dp') || '')) { WB.dpFmtLast = el.id; dpFmtSync() }
  })

  /** The ribbon's pressed states follow the text under the cursor. */
  function dpFmtSync() {
    if (typeof document.querySelectorAll !== 'function') return
    var btns = document.querySelectorAll('[data-wb-fmt]')
    if (!btns.length) return
    var el = dpFmtTarget()
    for (var i = 0; i < btns.length; i++) {
      var f = btns[i].getAttribute('data-wb-fmt')
      var on = false
      if (el) {
        if (f === 'bold' || f === 'italic' || f === 'underline' || f === 'strikeThrough') { try { on = dpCurrent() === el && document.queryCommandState(f) } catch (_e) { on = false } }
        else if (f.indexOf('align-') === 0) on = (el.getAttribute('data-wb-align') || '') === f.slice(6)
        else if (f === 'list') on = el.classList.contains('wb-outline-kind-list')
        else if (f === 'numlist') on = dpFieldNumbered(el)
      }
      btns[i].setAttribute('aria-pressed', on ? 'true' : 'false')
      btns[i].classList.toggle('is-on', on)
    }
    // The drop-downs show the format of the text under the cursor / of the paragraph.
    var sels = document.querySelectorAll('[data-wb-fmtsel]')
    var anchor = null
    try {
      var sl = window.getSelection()
      var an = sl && sl.anchorNode
      anchor = an && an.nodeType === 3 ? an.parentNode : an
      if (!el || !anchor || !el.contains(anchor)) anchor = null
    } catch (_e) { anchor = null }
    for (var j = 0; j < sels.length; j++) {
      if (document.activeElement === sels[j]) continue
      var kind = sels[j].getAttribute('data-wb-fmtsel')
      var v = ''
      var pf = el ? dpPfmtOf(el) : {}
      if (kind === 'linesp') v = pf.ls ? String(pf.ls) : ''
      else if (kind === 'spaceafter') v = pf.sa !== undefined && pf.sa !== null ? String(pf.sa) : ''
      else if (kind === 'heading') v = pf.h ? String(pf.h) : ''
      else if (anchor) {
        try {
          var cs = window.getComputedStyle(anchor)
          if (kind === 'font') v = dpFontOf(cs.fontFamily)
          else if (kind === 'size') { var z = dpPtOf(cs.fontSize); v = DP_SIZES.indexOf(z) >= 0 ? String(z) : '' }
        } catch (_e) { v = '' }
      }
      var has = false
      for (var o = 0; o < sels[j].options.length; o++) if (sels[j].options[o].value === v) has = true
      sels[j].value = has ? v : ''
    }
  }
  document.addEventListener('selectionchange', function () { if (WB.open) dpFmtSync() })

  function dpSetAlign(el, a, force) {
    var cur = el.getAttribute('data-wb-align') || ''
    var next = force !== undefined ? force : (cur === a ? '' : a)
    DP_ALIGNS.forEach(function (x) { el.classList.remove('wb-dp-al-' + x) })
    if (next) { el.classList.add('wb-dp-al-' + next); el.setAttribute('data-wb-align', next) } else el.removeAttribute('data-wb-align')
    dpMarkDirty()
  }

  function dpToggleList(el) {
    var bid = el.getAttribute('data-wb-block')
    var b = bid ? findBlock(bid) : null
    if (b && b.kind !== 'paragraph' && b.kind !== 'list') return
    var was = el.getAttribute('data-wb-kind') || (b ? b.kind : 'paragraph')
    var k = was === 'list' ? 'paragraph' : 'list'
    el.setAttribute('data-wb-kind', k)
    el.classList.toggle('wb-outline-kind-list', k === 'list')
    el.classList.toggle('wb-outline-kind-paragraph', k !== 'list')
    if (k !== 'list') el.classList.remove('wb-dp-numbered')
    dpMarkDirty()
  }

  /**
   * #562: a list button over several selected paragraphs has ONE outcome for all of them (as the alignment buttons do):
   * when every paragraph already is that kind of list the list comes off, otherwise every paragraph becomes one. A toggle
   * per paragraph turned a half-listed selection into the opposite half-listed selection.
   */
  function dpToggleListOver(els, numbered) {
    var listable = els.filter(function (x) {
      var bid = x.getAttribute('data-wb-block')
      var b = bid ? findBlock(bid) : null
      if (numbered && !dpText(x).trim()) return false // an empty line has nothing to number
      return !(b && b.kind !== 'paragraph' && b.kind !== 'list')
    })
    var isOn = function (x) {
      return numbered ? dpFieldNumbered(x) : (x.getAttribute('data-wb-kind') || (findBlock(x.getAttribute('data-wb-block') || '') || {}).kind || 'paragraph') === 'list'
    }
    var turnOn = !listable.every(isOn)
    var todo = listable.filter(function (x) { return isOn(x) !== turnOn })
    if (!(numbered && turnOn)) {
      todo.forEach(function (x) { if (numbered) dpToggleNumList(x); else dpToggleList(x) })
      return
    }
    // A numbered list is ONE list block (the PDF / Word number a block's lines 1, 2, 3): paragraphs that follow each other
    // become the lines of one list, so the page shows -- and the PDF prints -- 1, 2, 3 and not 1, 1, 1.
    var runs = []
    todo.forEach(function (x) {
      var last = runs.length ? runs[runs.length - 1] : null
      if (last && dpNeighbour(last[last.length - 1], 1) === x) last.push(x)
      else runs.push([x])
    })
    runs.forEach(function (run) {
      if (run.length < 2) { dpToggleNumList(run[0]); return }
      var strip = function (l) { return l.replace(/^\s*(?:[-*\u2022\u2013]|\d+[.)])\s+/, '') }
      var lines = []
      run.forEach(function (x) { dpText(x).split('\n').forEach(function (l) { if (l.trim()) lines.push(strip(l)) }) })
      var first = run[0]
      first.setAttribute('data-wb-kind', 'list')
      first.classList.add('wb-outline-kind-list', 'wb-dp-numbered')
      first.classList.remove('wb-outline-kind-paragraph')
      first.textContent = lines.map(function (l, i) { return (i + 1) + '. ' + l }).join('\n')
      run.slice(1).forEach(function (x) { dpDropRow(x) })
      dpMarkDirty()
    })
  }

  /** Paragraph format of the field: merge `patch` (null / '' removes a key), show it at once, save it for a stored block. */
  function dpSetPfmt(el, patch) {
    var p = dpPfmtOf(el)
    var hBefore = p.h || 0
    Object.keys(patch).forEach(function (k) {
      if (patch[k] === null || patch[k] === '' || patch[k] === undefined) delete p[k]
      else p[k] = patch[k]
    })
    // #534 (c): the chapter border is the Heading 1 paragraph. A paragraph made Heading 1 starts a new chapter at the next
    // save; a chapter title made anything else is joined to the chapter above it.
    var kindOf = el.getAttribute('data-wb-dp')
    if (kindOf === 'sec') {
      if (p.h !== 1 && patch.h !== undefined) el.setAttribute('data-wb-demote', '1')
    } else if (p.h === 1 && hBefore !== 1) el.setAttribute('data-wb-split', '1')
    else if (p.h !== 1) el.removeAttribute('data-wb-split')
    if (p.ls === 1) delete p.ls
    el.classList.remove('wb-dp-h1', 'wb-dp-h2', 'wb-dp-h3')
    if (p.h) el.classList.add('wb-dp-h' + p.h)
    if (Object.keys(p).length) {
      el.setAttribute('data-wb-pfmt', JSON.stringify(p))
      el.setAttribute('style', dpPfmtStyle(p))
    } else {
      el.removeAttribute('data-wb-pfmt')
      el.removeAttribute('style')
    }
    dpMarkDirty()
  }

  function dpIsNumbered(text) {
    var lines = String(text || '').split('\n').filter(function (l) { return l.trim() })
    return lines.length > 0 && lines.every(function (l) { return /^\s*\d+[.)]\s+/.test(l) })
  }

  /** Is the field a numbered list? A stored list shows its lines without the markers, so the stored text decides. */
  function dpFieldNumbered(el) {
    // The page keeps the state on the field itself (a stored list shows the same lines the stored text has).
    if (el.classList.contains('wb-dp-numbered') && el.classList.contains('wb-outline-kind-list')) return true
    var bid = el.getAttribute('data-wb-block')
    if (bid && !el.getAttribute('data-wb-kind')) { var b = findBlock(bid); if (b) return b.kind === 'list' && dpIsNumbered(b.text) }
    return el.classList.contains('wb-outline-kind-list') && dpIsNumbered(dpText(el))
  }

  /** Numbered list: every line gets "1. 2. 3." (the list renders as a real numbered list); pressed again, it is plain text. */
  function dpToggleNumList(el) {
    var bid = el.getAttribute('data-wb-block')
    var b = bid ? findBlock(bid) : null
    if (b && b.kind !== 'paragraph' && b.kind !== 'list') return
    var text = dpText(el)
    var numbered = dpFieldNumbered(el)
    var strip = function (l) { return l.replace(/^\s*(?:[-*•–]|\d+[.)])\s+/, '') }
    var lines = text.split('\n').filter(function (l) { return l.trim() })
    var next = numbered ? lines.map(strip).join('\n') : lines.map(function (l, i) { return (i + 1) + '. ' + strip(l) }).join('\n')
    var kind = numbered ? 'paragraph' : 'list'
    if (!next) return
    el.setAttribute('data-wb-kind', kind)
    el.classList.toggle('wb-outline-kind-list', kind === 'list')
    el.classList.toggle('wb-outline-kind-paragraph', kind !== 'list')
    el.classList.toggle('wb-dp-numbered', kind === 'list')
    el.textContent = next
    dpMarkDirty()
  }

  /** Remember the selection inside the document fields: a drop-down or a colour picker takes the focus away from it. */
  document.addEventListener('selectionchange', function () {
    if (!WB.open) return
    try {
      var sel = window.getSelection()
      if (!sel || !sel.rangeCount) return
      var r = sel.getRangeAt(0)
      var host = r.commonAncestorContainer
      host = host && host.nodeType === 3 ? host.parentNode : host
      var f = host && typeof host.closest === 'function' ? host.closest('[data-wb-dp]') : null
      if (f && f.id && /^sec$/.test(f.getAttribute('data-wb-dp') || '')) WB.dpRange = { id: f.id, range: r.cloneRange() } // #604: a font / size / colour picked from a list takes the focus away from a title too
      else if (f && f.id && /^(block|new)$/.test(f.getAttribute('data-wb-dp') || '')) { WB.dpRange = { id: f.id, range: r.cloneRange() }; WB.dpFmtLast = f.id }
      else if (!r.collapsed && host && typeof host.closest === 'function' && host.closest('.wb-dp-page[contenteditable="true"]')) {
        // #562 (Boss TG 8935): a selection over SEVERAL paragraphs is one selection -- it used to be forgotten here, so a
        // font size picked from the list landed on whatever single paragraph had been selected before.
        var many = dpRangeFields(r)
        if (many.length > 1) { WB.dpRange = { id: many[many.length - 1].id || '', range: r.cloneRange(), multi: true }; if (many[many.length - 1].id) WB.dpFmtLast = many[many.length - 1].id }
      }
      // The paragraph the cursor is in is marked (the page is one editing host: :focus-within would mark all).
      var rootEl = dpRoot()
      if (rootEl) {
        var was = rootEl.querySelector('.is-cur')
        var row = f && typeof f.closest === 'function' ? f.closest('.wb-dp-row, .wb-dp-sechead') : null
        if (was && was !== row) was.classList.remove('is-cur')
        if (row && !row.classList.contains('is-cur')) row.classList.add('is-cur')
      }
      if (WB.dpTblEdit) dpTblLeaveCheck()
    } catch (_e) { /* nem baj */ }
  })

  /** The writable paragraphs a range touches (the page is one editing host, a paragraph is a field in it). */
  function dpRangeFields(range) {
    var root = dpRoot()
    if (!root || !range) return []
    var out = []
    var all = root.querySelectorAll('.wb-dp-edit[data-wb-dp="block"], .wb-dp-edit[data-wb-dp="new"]')
    for (var i = 0; i < all.length; i++) {
      var n = all[i]
      if (n.classList.contains('wb-outline-kind-table')) continue
      try {
        if (!range.intersectsNode(n)) continue
        // A range that only ENDS at the very start of a paragraph (a triple click does that) has nothing selected in it.
        var probe = document.createRange()
        probe.selectNodeContents(n)
        if (range.compareBoundaryPoints(Range.START_TO_END, probe) <= 0 || range.compareBoundaryPoints(Range.END_TO_START, probe) >= 0) continue
        out.push(n)
      } catch (_e) { /* a detached node: not part of it */ }
    }
    return out
  }

  /** A paragraph made Heading 1: the title (at most 200 characters, ending at the last whole word that fits) and the rest. */
  function dpSplitTitle(text) {
    var full = String(text || '').replace(/\s*\n\s*/g, ' ').trim()
    var rest = ''
    if (full.length > 200) {
      var cut = full.lastIndexOf(' ', 200)
      if (cut < 80) cut = 200
      rest = full.slice(cut).trim()
      full = full.slice(0, cut).trim()
    }
    return { title: full, rest: rest }
  }

  /** What the Style box applies to: the selected paragraphs AND the chapter titles inside the selection (else `el`). */
  function dpHeadingEls(el) {
    var r = WB.dpRange
    var root = dpRoot()
    if (!r || !r.multi || !root) return [el]
    var out = dpRangeFields(r.range).filter(function (n) { return !!String(n.textContent || '').trim() })
    var titles = root.querySelectorAll('.wb-dp-edit[data-wb-dp="sec"]')
    for (var i = 0; i < titles.length; i++) { try { if (r.range.intersectsNode(titles[i])) out.push(titles[i]) } catch (_e) { /* detached */ } }
    return out.length > 1 ? out : [el]
  }

  /** The paragraphs a paragraph-level command applies to: all the selected ones, else the one the cursor is in. */
  function dpFmtEls(el) {
    var r = WB.dpRange
    if (r && r.multi) {
      var many = dpRangeFields(r.range)
      if (many.length > 1) return many
    }
    return [el]
  }

  function dpRestoreRange(el) {
    var r = WB.dpRange
    if (!r || (!r.multi && r.id !== el.id)) return false
    try {
      dpFocusRoot()
      var s = window.getSelection()
      s.removeAllRanges()
      s.addRange(r.range)
      return true
    } catch (_e) { return false }
  }

